import { Image, Linking, Pressable, Text, View } from 'react-native';
import { useTheme } from '@/lib/theme';
import { moreAppsFor, moreAppsIconUri, moreAppsStoreUrl } from '@/lib/moreApps';
import { Section, SettingsPage, TrailingMark, rowStyle, ROW_MIN_HEIGHT } from '@/components/settings-list';

// The shared More apps list (app-release standards): the owner's other live apps, each opening its App Store page.
// The list is bundled (lib/moreAppsCatalog.ts, generated by the app-release skill), so it works offline; nothing is sent.
export default function MoreApps() {
  const theme = useTheme();
  const apps = moreAppsFor(process.env.EXPO_OS || '', 'com.astrojams.newsworthy');
  return <SettingsPage>
    <Section testID="more-apps-list">
      {apps.map((app, index) => <Pressable key={app.id} testID={`more-apps-${app.id}`} accessibilityRole="link"
        accessibilityLabel={`${app.name}, ${app.subtitle}`} accessibilityHint="Opens the App Store"
        onPress={() => { void Linking.openURL(moreAppsStoreUrl(app)).catch(() => {}); }} style={rowStyle()}>
        <Image source={{ uri: moreAppsIconUri(app) }} accessibilityIgnoresInvertColors style={{ width: 40, height: 40, borderRadius: 9, marginRight: 14 }} />
        <View style={{ flex: 1, flexDirection: 'row', alignItems: 'center', alignSelf: 'stretch', gap: 12, minHeight: ROW_MIN_HEIGHT, paddingRight: 16,
          paddingVertical: 8, borderTopWidth: index === 0 ? 0 : 1, borderTopColor: theme.rule }}>
          <View style={{ flex: 1 }}>
            <Text style={{ color: theme.ink, fontSize: 17 }}>{app.name}</Text>
            <Text style={{ color: theme.muted, fontSize: 15 }}>{app.subtitle}</Text>
          </View>
          <TrailingMark name="external" color={theme.muted} />
        </View>
      </Pressable>)}
    </Section>
  </SettingsPage>;
}
